import sys, json

sys.stdout.reconfigure(encoding='utf-8')

def load_rt(fname, lang='ru'):
    with open(f'data/guidelines/esc-hf-2026/{fname}', 'r', encoding='utf-8') as f:
        data = json.load(f)
    num = data.get('number', '')
    title = data.get('title', {}).get(lang, '')
    out = [f"### {num} — {title}\n", "| Рекомендации | Класс | Уровень |", "|---|---|---|"]
    for sec in data.get('sections', []):
        for r in sec.get('rows', []):
            txt = r.get('text', {}).get(lang, '').replace('\n', ' ')
            cls = r.get('class', '')
            lvl = r.get('level', '')
            out.append(f"| {txt} | **{cls}** | **{lvl}** |")
    return "\n".join(out)

def load_t20(lang='ru'):
    with open('data/guidelines/esc-hf-2026/t20-red-flags-cardiac-amyloidosis.json', 'r', encoding='utf-8') as f:
        data = json.load(f)
    title = data.get('title', {}).get(lang, '')
    out = [f"#### Таблица 20: {title}\n", 
           "| «Красный флаг» | TTR | AL |",
           "|---|---|---|"]
    for r in data.get('rows', []):
        if r.get('kind') == 'section':
            sec_text = r.get('cells', [])[0].get('text', {}).get(lang, '')
            out.append(f"| **{sec_text}** | | |")
        else:
            cells = [c.get('text', {}).get(lang, '').replace('\n', ' ') for c in r.get('cells', [])]
            if len(cells) == 3:
                out.append(f"| {cells[0]} | {cells[1]} | {cells[2]} |")
    return "\n".join(out)

